window.products.push({"id":388348,"name":"Polylok 20\" / 24\" Septic Tank Riser Adapter Ring (PN: 3009-AR)","category":"homeandappliances","retail price":66.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31Sc6PQaLBL._AC_.jpg","description":"NOTE: This adapter will only work for PolyLok Risers. Tuf-Tite risers will NOT work with this adapter ring. The Polylok square riser adapter ring is designed to connect the Polylok septic tank risers or lids to an existing concrete tank with large square or round openings. The adapter ring mounts directly to the tank and accepts the risers and lids as attachments. Adapter ring accepts either 20\" or 24\" Riser Covers up to 25\" square opening Perfect for retrofitting onto existing tanks","images":["https://m.media-amazon.com/images/I/31Sc6PQaLBL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Polylok","source_asin":"B00JF8MSCQ","category_path":"Home & Kitchen"},"sku":"BM-388348","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00JF8MSCQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00JF8MSCQ","price_pending":true,"merchant_ready":false});
